from pysat.solvers import Solver

def solve(n):
    def var(i,j,v): return (i*n+j)*n+v+1
    clauses=[]
    # each cell exactly one
    for i in range(n):
      for j in range(n):
        clauses.append([var(i,j,v) for v in range(n)])
        for a in range(n):
          for b in range(a+1,n): clauses.append([-var(i,j,a),-var(i,j,b)])
    # rows: each val exactly once (at least implied by cell + atmost? need at least for Latin)
    for i in range(n):
      for v in range(n):
        clauses.append([var(i,j,v) for j in range(n)])
        for j1 in range(n):
          for j2 in range(j1+1,n): clauses.append([-var(i,j1,v),-var(i,j2,v)])
    # cols
    for j in range(n):
      for v in range(n):
        clauses.append([var(i,j,v) for i in range(n)])
        for i1 in range(n):
          for i2 in range(i1+1,n): clauses.append([-var(i1,j,v),-var(i2,j,v)])
    # diagonal
    for i in range(n): clauses.append([var(i,i,i)])
    # QG3: if xij=a and xji=b then xab=i
    for i in range(n):
      for j in range(n):
        for a in range(n):
          for b in range(n): clauses.append([-var(i,j,a), -var(j,i,b), var(a,b,i)])
    print('n',n,'vars',n*n*n,'clauses',len(clauses))
    with Solver(name='glucose4', bootstrap_with=clauses) as s:
      r=s.solve()
      print('solve',r)
      if r:
        mod=set(l for l in s.get_model() if l>0)
        grid=[[next(v for v in range(n) if var(i,j,v) in mod) for j in range(n)] for i in range(n)]
        for row in grid: print(row)
        print([z for row in grid for z in row])
      return r
for n in [4,5,6,7,8]:
    solve(n)
